def close(self):
    with self.condition:
        self.closed = True
        # Unblock consumers and pause() callers waiting for in-flight work.
        if self.error is None:
            self.error = RuntimeError("Rollout scheduler is closed")
        self.condition.notify_all()
    if self.thread is not None:
        self.thread.join()

