def pause(self, *, drain=True):
    with self.condition:
        previous = self.paused
        self.paused = True
        while self.running and self.error is None and (not self.admission_paused or (drain and self.active)):
            self.condition.wait()
        if self.error is not None:
            raise self.error
        return previous

