def wait(self, predicate):
    with self.condition:
        ready = self.condition.wait_for(lambda: self.error or self.done or predicate(self.events), timeout=180)
        if self.error:
            raise self.error
        assert ready and predicate(self.events), f"Probe failed on {self.url}: {self.events[-3:]}"

